targetBinaries.command:
ssh -o BatchMode=yes root@<hostId> 'python3 -c "import os,stat
for c in [\"/usr/bin/python3\",\"/bin/python3\",\"/sbin/runuser\",\"/usr/sbin/runuser\",\"/usr/bin/systemd-run\",\"/bin/systemd-run\",\"/bin/systemctl\",\"/usr/bin/systemctl\",\"/usr/bin/flock\",\"/bin/flock\"]:
    try: l=os.lstat(c)
    except OSError: print(c,\"MISSING\"); continue
    r=os.path.realpath(c)
    try: t=os.stat(r)
    except OSError: print(c,\"UNRESOLVABLE\",r); continue
    print(c,\"link=%s\"%stat.S_ISLNK(l.st_mode),\"realpath=%s\"%r,\"ok=%s\"%(l.st_uid==0 and t.st_uid==0 and stat.S_ISREG(t.st_mode) and os.access(r,os.X_OK)))"'

